('f59580d8-05d5-4f1b-80c8-c0ab5504dbdb', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4b00bce9-22fe-4eba-9cf8-3353b0a25501", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "424f9361-a8bd-4bac-a753-384ec037705e", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "e64abc78-57a5-464d-8316-5d2458fdd7c9", "text": "A tető színét", "isCorrect": false}, {"id": "c5ed33c4-1fcd-4e4d-a2f5-16f4f8bcad5b", "text": "Az épület magasságát", "isCorrect": false}, {"id": "a125a40b-0d45-48db-b827-7679971d96d0", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "13173912-f63f-453f-9312-bb94dff1b10f", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "448f6e67-a135-452a-813e-adc9e9d8a842", "text": "Igaz", "isCorrect": true}, {"id": "f296e36b-1b8e-4437-a559-35e93eef0bf4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20fde0bf-b05d-464e-88fb-b4ec9bccdf78", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6497447b-812f-4296-850a-80f8f83dd72b", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "0ea71e57-dcd1-4edc-9d80-052bdcd14327", "text": "Igaz", "isCorrect": true}, {"id": "3da8644f-bccf-442e-bc3d-0c7fc418f2e2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "54785ee8-8da0-4cd4-846d-f028da9dd59a", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "6d9f69f9-3ad0-415e-bc52-54161063e5b4", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "0047c7c1-2732-421c-9e4e-a2f716c3e710", "text": "Igaz", "isCorrect": true}, {"id": "cf8f972e-2d1a-47c4-8798-6533441a80a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "14633a04-4fc8-41a4-b64f-f4ef47994636", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('22f6b68c-aab5-478e-b8fb-7aa0278a6240', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "7cbc0bd7-df26-4d88-9cd8-63a5ecc1616a", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2761d52b-e30c-41cc-a106-3f778eef1f7a", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "adb443be-2699-455e-85db-c2ffb949ffba", "text": "Igaz", "isCorrect": true}, {"id": "804fe73c-72e9-4288-b119-ecf3ebfd0d39", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ac7aa485-151c-4571-92fb-fd3d58be3ead", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "caf1a9a6-8d07-4422-a196-c71aad291930", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "9418a64f-f934-4053-af4a-0b6dff599004", "text": "Gömbökből", "isCorrect": false}, {"id": "278b4a6c-6dd2-41cd-a328-39703580a9ed", "text": "Kúpokból", "isCorrect": false}, {"id": "84566414-da29-4890-8e3f-488a6bcffc7d", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "6be5ca48-a2ae-46ea-a728-147beaff3105", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "ed151b5e-e8e8-4dbe-883c-838ef5beca08", "text": "Igaz", "isCorrect": true}, {"id": "f17917f2-5be1-4860-96c2-5b1b16bbbb52", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc81715b-1cdc-4140-a0a8-3960a09b5a7e", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "78eb951e-eb29-440d-b074-