('2bda1c5a-e487-4fa2-91a7-2c462ee649dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "5fe7235e-2fa9-448a-861a-3a3e072b8371", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "39d8018f-2793-4ae4-91d5-95e9304e6529", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "06555ea6-adaf-4fcd-af26-87dce18862b5", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "93ded257-9d77-427e-9f36-f47246d7e6f0", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "d6fac6d4-f511-466c-a043-242d581b6935", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "ad0a067c-30d7-4979-9f17-fe3cfde9fa90", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "46ab66f2-90b6-4107-a109-e3ab878ce404", "text": "Igaz", "isCorrect": true}, {"id": "13d7c1d6-60f6-4dc6-b5dc-ca79526244ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2772082a-6d3c-4953-b455-91503ade841c", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "603dfba3-e757-4f52-ae33-cc30d5267aee", "text": "Igaz", "isCorrect": true}, {"id": "c0463fec-12dc-42dd-9ff6-7022c269c7cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4663c6c8-72b5-4f18-8afd-1db6ff9297a0", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "0fe47786-e7ca-45f4-91d1-71ea2ccfa6ed", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "9511bdc7-e2fa