('476491d0-d604-4cd2-9497-7977ee3237fc', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "ae5b6e2c-5d13-43d9-b587-fa3bf026c56f", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "572134ba-8daa-4cd8-b879-c3fdbb49fef5", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "98a539cf-6df7-49db-9638-cdb6957d0fa3", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "601098d1-02b1-44de-9845-ccd2cfb906ee", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "499378fe-a8d0-42b1-a12a-13a0032e8963", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "20fb6fd8-d095-4462-8d27-8be3955663ce", "text": "Igaz", "isCorrect": true}, {"id": "92c25f2e-efba-47bc-a789-3d29f19a36ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "202981fe-d702-4471-8bb6-c07b11a1862d", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "51111e70-8bc3-4f2c-99ad-37cb314ab48c", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "6ec3ed88-1690-4f65-9030-24b16b792da9", "text": "Igaz", "isCorrect": true}, {"id": "ddb9161c-105d-4389-9378-ba4b011e9b54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d55beff5-7b7b-4261-8a54-e84d3e04adcb', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d8d029ba-90e9-47b9-83fc-e154d52aefd2", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "6be11eea-71f7-4d12-b41e-7ae5edddd89c", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "4f38d16f-10a1-4b04-a607-a1ddd295afa8", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "898e3088-98f3-4077-8895-a7168895fc29", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "7e37f465-7282-44ff-a3f8-bc36561eb254", "text": "Igaz", "isCorrect": true}, {"id": "eef54840-5b3d-45dc-bf54-dce626633be7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "caf1748d-0bc3-4266-a1c0-42a8cbe039b0", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "235d1366-0f0b-4b7f-8c76-7acfa0e38ba0", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "1b96a333-1330-43b0-b9b6-dc279cbf12dd", "text": "Igaz", "isCorrect": true}, {"id": "33224e81-6856-4529-a76f-a644fd11a8a8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aef58829-90a3-4b2c-bd45-58d0cb82151a", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW()),
('a4afc9e9-e3a6-4fb6-a173-b31731c8aa21', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "53a4a18f-d1ce-4129-aa5e-10c59e4bbaaf", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "b3561eff-e09d-4495-af18-f621cc7e8362", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "a1de089b-4a75-49f5-ac06-2ca480b20a1a", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "85bb939c-e45e-40e4-9416-03c761ee1a94", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "d8368f16-1d3f-4bcc-a4ca-0bd2f57e2e59", "text": "Igaz", "isCorrect": true}, {"id": "bed18a2d-a560-4594-b4cb-786f4c30e767", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "449e7133-ce93-4f15-b13d-e24188b73d81", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "8a61ad37-3275-40cb-8d40-82b9ee94ff10", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "5b112f45-ed6c-4da0-b828-ff7325be52c3", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "b32dc491-d70a-4809-8c94-412c98ba4b40", "text": "Igaz", "isCorrect": true}, {"id": "205337e6-e6d5-42df-8d01-c0cab28866f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('b81c67a1-cb97-4ed1-aaea-ce9a2a441633', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3152181a-1870-4bde-89a8-73d755bbcff5", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "5e023094-201e-4f00-878f-f2c571b292d3", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "586285dc-328f-4bec-b549-77aaffce7b86", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "791b0226-d760-4f6b-b45e-5db9f4495978", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "3f0f7987-6203-401f-90ac-0f3e9d8d4ea4", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "ce3b57f8-2a81-4a89-9541-943a802a5e20", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "933451f8-ccf4-4203-8ca3-283396183ce1", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "10584fc5-13d7-4423-9913-3c78e7e29e4a", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "c8f925cb-1ce8-468e-8d00-3621266f5108", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "200d322a-ceca-4b15-a28b-ef913bdddc19", "text": "Igaz", "isCorrect": true}, {"id": "e77d4864-73ee-43bb-b037-1b9dce7238c5", "te