('ea3a3349-3a15-4bbc-8556-df60f035f034', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "2fd3d612-a37b-4ef7-aa04-35e0f2fa994b", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "c1f0eff1-5388-43d9-a7b3-28a01a740342", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "b8a7180c-4d32-46b1-8b65-0db0f1804872", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "ae66a403-7c7f-4624-9ea8-c339ad6dace3", "text": "A számláló írása", "isCorrect": false}, {"id": "5d6b1f8e-0bdb-416d-a068-450007cae0e5", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "319c43a7-8835-41fe-ac3e-1760c8c12762", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "8e655030-9034-45c9-90bf-7c13264406b3", "text": "Igaz", "isCorrect": true}, {"id": "fb38f38f-fbe3-4de2-962b-09c8771927e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "94c22c04-8934-4691-9323-e087ffbbcc6f", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "0b565373-1920-425c-8be9-537c85b753bc", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "a029ee40-8f79-41d7-a407-01b8130cddc2", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "2e899b1a-683e-4c3f-9c71-2f84bbbb3cc6", "text": "Igaz", "isCorrect": true}, {"id": "64ce3775-5c34-44d2-8dde-2b0e1d9e8dd4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0e2b418a-4bb6-4af0-b1b3-c2420cf81a43", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög terüle