('df285655-bc02-4c7f-8f06-04fb3cff26d1', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "5e0372af-0c78-4650-aa03-15aead32738c", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "0bee0621-2019-4966-b9c4-bcbc221e1a9f", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "cd6aa687-f14b-4c6a-a366-1f4cf9cf626e", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "a68a469a-c3b9-42ab-b75d-a5331dcafafe", "text": "Számok törlése", "isCorrect": false}, {"id": "41172419-829c-44bb-8c28-574c84111075", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "f432bb29-c886-4474-90d1-310ac450ba48", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "e570326e-6526-49bf-a367-9ee1b9a5e13b", "text": "Igaz", "isCorrect": true}, {"id": "ec017e7f-c608-44df-a9d3-531d0b106261", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "580de1c5-862d-4be9-85d5-aa163dcb5d8c", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "2efbf9ce-14ec-4dc3-9b15-0f4664b820c8", "text": "Alvás", "isCorrect": true}, {"id": "a2ded367-7c94-481d-a4c0-68ef638de5ad", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "7ef5a028-6396-4b9c-bdb0-73edd0021afa", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "0de9a9a4-172e-4564-8fb5-2adcfed1b926", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "0b413c49-bed9-4a6f-bf91-b8e008701c06", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "19b901ce-c9f2-4c56-9268-76ee8453b1f1", "text": "Igaz", "isCorrect": true}, {"id": "43296d41-33e9-46ed-afab-c979a13f5621", "text": "Hamis