('5bcb5dfe-71aa-4b41-bbc1-b943256afffd', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "8b95e038-2d13-473a-bb95-897bd26d2ea5", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "4573a0fa-6045-45a0-b882-f6ae5198773e", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "7a49d8fb-1d78-4b9a-a396-ada47db54a4b", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "a328435d-c66d-4027-8f92-b370aaf65f28", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "9770aa1c-b74f-494e-a19c-b5f81500d41f", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "e74a780b-634f-4bc9-b99b-db510f27f500", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "c981fe27-169a-42ee-a1df-ad43ee203e84", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "b1815964-a986-4aac-99a1-0719afa53637", "text": "Számok összeadására", "isCorrect": false}, {"id": "74d9190a-7597-4020-bb00-c6f36df24004", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "a7e33d6c-6564-4aea-8dfd-4f444ebef7cc", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "e9570638-53e9-45cf-9665-ebb53a256f5b", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "15f2a046-866c-4caa-8b60-7d802c69431a", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "c9e0af94-2635-47d1-9c1f-00fa61ebafdd", "text": "Igaz", "isCorrect": true}, {"id": "b37dd46b-28e5-4051-9acd-b2ecb663a057", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfae8ff4-2c77-4aaa-bb94-fe373ed4be91", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "2c11dd05-1b9a-4b8e-977a-a9cffbd3401e", "text": "Igaz", "isCorrect": true}, {"id": "f1731e5d-4c65-4d65-ac9e-c3440c805696", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f0bca8e4-39df-47f6-8004-12e773a09871", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "05fc8788-917e-4548-ba25-af3a97010932", "text": "Igaz", "isCorrect": true}, {"id": "327f45c5-0c47-48f7-be83-76abf6567473", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dafd1cf9-0551-4583-88c4-6e0cd0de9921", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;